    # those points already share a vertical line.
    # For points with different x but same y, they share horizontal line.
    # For points with different x and different y, we need to add an intersection.

    # Simple approach: create a grid with all possible intersections
    # This ensures the "good" property
    result = set(points)

    # For each pair of points with different x and y
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            x1, y1 = points[i]
            x2, y2 = points[j]

            if x1 != x2 and y1 != y2:
