def get_new_virus_prefix(k, char, virus):
    """
    Given current virus prefix of length k and a new character,
    return the new prefix length after adding char.
    """
    if k == 0:
        if char == virus[0]:
            return 1
        return 0
    if k > 0 and char == virus[k - 1]:
