    n, m, v_len = len(s1), len(s2), len(virus)

    v_len = max(v_len, 1)

    # dp[(i, j, k)] = (length, (prev_i, prev_j, prev_k))
    # k = current virus prefix match length
    dp = {}
    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len):
                dp[(i, j, k)] = (0, (-1, -1, -1))

    dp[(0, 0, 0)] = (0, (-1, -1, -1))

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len):
                cur_i, cur_j, cur_k = i, j, k
                cur_len = dp[(cur_i, cur_j, cur_k)][0]

                # Skip s1[i] - advance only i
                if cur_i < n:
                    next_i, next_j, next_k = cur_i + 1, cur_j, cur_k
                    next_len = cur_len
                    if (next_i, next_j, next_k) not in dp or dp[(next_i, next_j, next_k)][0] < next_len:
                        dp[(next_i, next_j, next_k)] = (next_len, (cur_i, cur_j, cur_k))

                # Skip s2[j] - advance only j
                if cur_j < m:
                    next_i, next_j, next_k = cur_i, cur_j + 1, cur_k
                    next_len = cur_len
                    if (next_i, next_j, next_k) not in dp or dp[(next_i, next_j, next_k)][0] < next_len:
                        dp[(next_i, next_j, next_k)] = (next_len, (cur_i, cur_j, cur_k))

                # Try to match s1[i] and s2[j]
                if cur_i < n and cur_j < m and s1[cur_i] == s2[cur_j]:
                    char = s1[cur_i]
                    new_k = get_new_virus_prefix(cur_k, char, virus)

                    if new_k < v_len:
                        next_i, next_j, next_k = cur_i + 1, cur_j + 1, new_k
                        next_len = cur_len + 1
                        if (next_i, next_j, next_k) not in dp or dp[(next_i, next_j, next_k)][0] < next_len:
                            dp[(next_i, next_j, next_k)] = (next_len, (cur_i, cur_j, cur_k))

    # Find maximum length state
    max_len = 0
    result_state = (0, 0, 0)
    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len):
                if dp[(i, j, k)][0] > max_len:
                    max_len = dp[(i, j, k)][0]
                    result_state = (i, j, k)

    if max_len == 0:
        return "0"

    # Reconstruct result using parent pointers
    result = []
    curr_i, curr_j, curr_k = result_state
    while (curr_i, curr_j, curr_k) != (0, 0, 0):
        prev_i, prev_j, prev_k = dp[(curr_i, curr_j, curr_k)][1]
