```python
def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return '0'

    n = int(lines[0])
    adj = [[] for _ in range(n + 1)]

    for i in range(1, len(lines)):
        if lines[i]:
            parts = lines[i].split()
            if len(parts) >= 2:
                a, b = int(parts[0]), int(parts[1])
                adj[a].append(b)
                adj[b].append(a)

    sz = [0] * (n + 1)

    def compute_sz(u, p):
        sz[u] = 1
        for v in adj[u]:
            if v != p:
                compute_sz(v, u)
                sz[u] += sz[v]

    compute_sz(1, 0)

    dp = [[0] * (n + 1) for _ in range(n + 1)]

    def solve(u, p):
        # Initialize: u alone forms component of size 1 with product 1
        local_dp = [0] * (sz[u] + 1)
        local_dp[1] = 1
        cur_sz = 1

        for v in adj[u]:
            if v == p:
                continue
            solve(v, u)
            sz_v = sz[v]

            # Find max product from child v's subtree (when v forms separate component)
            max_v = max(dp[v][1:sz_v + 1])

            # New dp table after processing child v
            new_dp = [0] * (cur_sz + sz_v + 1)

            # Option 1: Merge v's component with u's component
            for i in range(1, cur_sz + 1):
                if local_dp[i] == 0:
                    continue
                for j in range(1, sz_v + 1):
                    if dp[v][j] > 0:
                        new_dp[i + j] = max(new_dp[i + j], local_dp[i] * dp[v][j])

            # Option 2: Cut edge to v (v's component becomes separate)
            for i in range(1, cur_sz + 1):
                if local_dp[i] == 0:
                    continue
                new_dp[i] = max(new_dp[i], local_dp[i] * max_v)

            local_dp = new_dp
            cur_sz += sz_v

        dp[u] = local_dp

    solve(1, 0)

    # Return maximum across all possible component sizes at root
    return str(max(dp[1][1:]))
```

This solution computes subtree sizes first, then uses tree DP to compute the maximum product for each possible component size at each vertex. For each vertex, we consider whether to merge each child's component or cut the edge.

