        # Check if endpoints alternate around the circle
        # Normalize ordering
        a1, b1 = min(a1, b1), max(a1, b1)
        a2, b2 = min(a2, b2), max(a2, b2)

        # Count how many endpoints of one chord appear between the other's endpoints
        def in_arc(start, end, x):
            if start <= end:
                return start <= x <= end
            return x >= start or x <= end

        n_endpoints = (a2, b2)
        in_first = sum(1 for x in n_endpoints if in_arc(a1, b1, x))

        if in_first == 0 or in_first == 2:
            return False
        return True

    for i in range(m):
        for j in range(i + 1, m):
