def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    N, M, K = map(int, lines[0].split())

    cell_energy = {}

    for i in range(1, K + 1):
        x, y, d, start_t, e = map(int, lines[i].split())

        pattern = [(x, y), (x + d, y - d), (x + d, y), (x, y + d)]

        for idx in range(4):
            px, py = pattern[idx]
            target_time = px + py

            if 0 <= px < N and 0 <= py < M and target_time >= start_t:
                offset_needed = target_time - start_t
                if offset_needed >= 0 and offset_needed % 4 == idx:
                    cell_energy[(px, py)] = cell_energy.get((px, py), 0) + e

    dp = [[0] * M for _ in range(N)]
    dp[0][0] = cell_energy.get((0, 0), 0)

    for r in range(N):
        for c in range(M):
