The key insight is that for the 2-edge case, I only need to check edges that are actually on some s-t path. I can identify these by computing reachability from s forward and from t backward.

```python
import sys
from collections import deque

def solution(input_str):
    data = input_str.strip().split()
    if not data:
        return "-1"

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    s = int(data[idx]); idx += 1
    t = int(data[idx]); idx += 1

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        w = int(data[idx]); idx += 1
        edges.append((u, v, w, i + 1))
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    # Check if s and t are already disconnected
    def is_connected(blocked):
        visited = {s}
        queue = deque([s])
        while queue:
            u = queue.popleft()
            if u == t:
                return False  # t is reachable
            for v, eidx in adj[u]:
                if eidx not in blocked and v not in visited:
                    visited.add(v)
                    queue.append(v)
        return True  # t is not reachable

    if is_connected(set()):
        return "0\n0\n"

    # Try removing 1 edge
    for i in range(m):
        if not is_connected({i}):
            cost = edges[i][2]
            return f"{cost}\n1\n{edges[i][3]}\n"

    # Find edges on s-t paths using forward and backward reachability
    s_reachable = set()
    q = deque([s])
    s_reachable.add(s)
    while q:
        u = q.popleft()
        for v, _ in adj[u]:
            if v not in s_reachable:
                s_reachable.add(v)
                q.append(v)

    t_reachable = set()
    q = deque([t])
    t_reachable.add(t)
    while q:
        u = q.popleft()
        for v, _ in adj[u]:
            if v not in t_reachable:
                t_reachable.add(v)
                q.append(v)

    s_t_edges = []
    for i, (u, v, w, idx_orig) in enumerate(edges):
        if (u in s_reachable and v in t_reachable) or (v in s_reachable and u in t_reachable):
            s_t_edges.append(i)

    # Try all pairs of edges on s-t paths
    best_cost = float('inf')
    best_pair = None

    for i in s_t_edges:
        for j in s_t_edges:
            if i != j:
                blocked = {i + 1, j + 1}
                if not is_connected(blocked):
                    cost = edges[i][2] + edges[j][2]
                    if cost < best_cost:
                        best_cost = cost
                        best_pair = (edges[i][3], edges[j][3])

    if best_pair:
        best_pair = sorted(best_pair)
        return f"{best_cost}\n2\n{best_pair[0]} {best_pair[1]}\n"

    return "-1"
