Looking at this problem, I need to count valid squares (both axis-aligned and diamond-shaped) in a binary matrix. A valid square must:
1. Have a solid frame of 1s with linewidth 1
2. Have interior of 0s
3. Not touch any foreign 1s (all exterior cells must be 0)
4. Be at least 2×2 for axis-aligned squares

Let me analyze the test case to understand the diamond pattern:
- The example shows a diamond with center at (2,2) and radius 1
- Points at Manhattan distance 1 from center form the border (all 1s)
- Center itself is 0
- All other cells must be 0

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        matrix = [list(lines[idx]) for _ in range(n)]
        idx += 1

        count = 0

        # Check axis-aligned squares (side >= 2)
        for top in range(n):
            for left in range(m):
                for side in range(2, min(n - top + 1, m - left + 1)):
                    bottom = top + side - 1
                    right = left + side - 1

                    valid = True

                    # Check all 4 edges are 1s
                    for c in range(left, right + 1):
                        if matrix[top][c] != 1 or matrix[bottom][c] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    for r in range(top, bottom + 1):
                        if matrix[r][left] != 1 or matrix[r][right] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check interior are 0s
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if matrix[r][c] != 0:
                                valid = False
                                break
                        if not valid:
                            break
                    if not valid:
                        continue

                    # Check no exterior 1s touch the square
                    for r in range(top - 1, bottom + 2):
                        for c in range(left - 1, right + 2):
                            if 0 <= r < n and 0 <= c < m:
                                # Check if (r,c) is outside the square
                                if not (top <= r < bottom and left <= c < right):
                                    if matrix[r][c] == 1:
                                        valid = False
                                        break
                        if not valid:
                            break

                    if valid:
                        count += 1

        # Check diamond-shaped squares
        for cr in range(n):
            for cc in range(m):
                for radius in range(1, min(n, m)):
                    # Check if diamond fits within bounds
                    if cr - radius < 0 or cr + radius >= n or cc - radius < 0 or cc + radius >= m:
                        continue

                    valid = True

                    # Diamond border: points at Manhattan distance = radius
                    # Center: at (cr, cc)

                    # Check center is 0
                    if matrix[cr][cc] != 0:
                        valid = False
                        continue

                    # Check all border points
                    for r in range(cr - radius, cr + radius + 1):
                        for c in range(cc - radius, cc + radius + 1):
                            distance = abs(r - cr) + abs(c - cc)
                            if distance == radius:
                                if matrix[r][c] != 1:
                                    valid = False
                                    break
                            elif distance < radius:
                                # Interior point (but not center for radius > 1)
                                if r != cr or c != cc:
                                    if matrix[r][c] != 0:
                                        valid = False
                                        break
                        if not valid:
                            break

                    if not valid:
                        continue

                    # Check all exterior points (Manhattan distance > radius) are 0
                    for r in range(max(0, cr - radius - 1), min(n, cr + radius + 2)):
                        for c in range(max(0, cc - radius - 1), min(m, cc + radius + 2)):
                            distance = abs(r - cr) + abs(c - cc)
                            if distance > radius:
                                if matrix[r][c] == 1:
                                    valid = False
                                    break
                        if not valid:
                            break

                    if valid:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
```

