    n = int(lines[0])
    x1, y1, x2, y2 = map(int, lines[1].split())

    # Invalid if rectangle doesn't exist (x1 >= x2 or y1 >= y2)
    if x1 >= x2 or y1 >= y2:
        return "-1"

    min_t = 0.0
    max_t = float('inf')

    for i in range(n):
        parts = lines[2 + i].split()
        rx, ry, vx, vy = map(int, parts)

        # Process X: x1 < rx + vx*t < x2
        # x1 < rx + vx*t
        if vx > 0:
            t = (x1 - rx) / vx
            if t > min_t:
                min_t = t
        elif vx < 0:
            t = (x1 - rx) / vx
            if t < max_t:
                max_t = t
        else:
            if rx <= x1:
                return "-1"

        # rx + vx*t < x2
        if vx > 0:
            t = (x2 - rx) / vx
            if t < max_t:
                max_t = t
        elif vx < 0:
            t = (x2 - rx) / vx
            if t > min_t:
                min_t = t
        else:
            if rx >= x2:
                return "-1"

        # Process Y: y1 < ry + vy*t < y2
        if vy > 0:
            t = (y1 - ry) / vy
            if t > min_t:
                min_t = t
        elif vy < 0:
            t = (y1 - ry) / vy
            if t < max_t:
                max_t = t
        else:
            if ry <= y1:
                return "-1"

        # ry + vy*t < y2
        if vy > 0:
            t = (y2 - ry) / vy
            if t < max_t:
                max_t = t
        elif vy < 0:
            t = (y2 - ry) / vy
            if t > min_t:
                min_t = t
        else:
            if ry >= y2:
                return "-1"

    if min_t >= max_t:
        return "-1"

    return "%.10f" % min_t
