    ci = list(map(int, lines[1].split()))

    # dp[s] = minimum days to achieve exactly sum s
    dp: Dict[int, int] = {0: 0}

    # Process each item (order doesn't matter for correctness)
    for c in ci:
        new_dp = dp.copy()
        for s, days in dp.items():
            # Can acquire item c if: s + d >= c
            if s + d >= c:
                new_s = s + c
                new_days = days + 1
                if new_s not in new_dp or new_dp[new_s] > new_days:
                    new_dp[new_s] = new_days
        dp = new_dp

    max_sum = max(dp.keys())
    min_days = dp[max_sum]

    return f"{max_sum} {min_days}"


